## 7-10. AI 친화 자원 추적 (YAML)

```yaml
resources:
  luck_tokens:
    current: 6
    max: 10  # LCK 5 × 2
    session_refresh: 5
    used_this_session:
      - {turn: 3, amount: 1, purpose: "재굴림"}
      - {turn: 7, amount: 2, purpose: "크리티컬 확정"}
      - {turn: 12, amount: 1, purpose: "에고 회복 1d6 → 3"}

  ego:
    current: 10
    max: 12  # max(PRE 6 × 2, 4)
    resistance_mod: 4  # max ÷ 3 내림
    damage_this_session:
      - {turn: 2, amount: -1, source: "에고 프레셔"}
      - {turn: 5, amount: -1, source: "설득 실패"}
    ego_shock_count: 0

  genre_resource:
    name: "DSR (차원 스트레스)"
    current: 6
    max: 14  # 8 + PRE 6
    increase_this_session:
      - {turn: 0, amount: +1, reason: "일반 차원 거주"}
      - {turn: 4, amount: +1, reason: "Effect 강화"}
      - {turn: 7, amount: +1, reason: "플래시백"}
    decrease_this_session:
      - {turn: 6, amount: -1, reason: "전투 승리"}
      - {turn: 10, amount: -1, reason: "관계 확인 RP"}

  trauma:
    count: 0
    list: []
    threshold_warnings:
      - {count: 4, status: "취약"}
      - {count: 4, ego_zero: true, status: "플라이어화 리스크"}

  d6_pool:
    current: 8
    max: 14  # BOD 8 + PRE 6
    session_start: 7  # 50% 충전
    supply_log:
      - {turn: 0, amount: +7, reason: "세션 시작 50%"}
      - {turn: 5, amount: +3, reason: "장전 행동 (REF Grade 27 ÷ 5)"}
    consumption_log:
      - {turn: 3, amount: -5, reason: "기관포 연사", hits: 3}
      - {turn: 8, amount: -10, reason: "범위 수류탄", hits: 5}
```

